-- Authentication hardening schema (PostgreSQL).
-- Password material must be an Argon2id encoded hash generated by trusted server code.
-- Never store plaintext passwords, reversible password encryption, or session bearer tokens.

CREATE TABLE IF NOT EXISTS user_credentials (
    user_id uuid PRIMARY KEY REFERENCES users(user_id) ON DELETE RESTRICT,
    password_hash varchar(500) NOT NULL,
    password_algorithm varchar(20) NOT NULL DEFAULT 'argon2id' CHECK (password_algorithm = 'argon2id'),
    password_changed_at timestamptz NOT NULL DEFAULT now(),
    password_expires_at timestamptz,
    failed_attempt_count integer NOT NULL DEFAULT 0 CHECK (failed_attempt_count >= 0),
    locked_until timestamptz,
    credential_version integer NOT NULL DEFAULT 1 CHECK (credential_version > 0),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS user_sessions (
    session_id uuid PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES users(user_id) ON DELETE RESTRICT,
    company_id uuid NOT NULL REFERENCES companies(company_id) ON DELETE RESTRICT,
    token_hash char(64) NOT NULL UNIQUE,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    revoked_at timestamptz,
    revoke_reason varchar(200),
    ip_address inet,
    user_agent varchar(1000),
    CHECK (token_hash ~ '^[0-9a-fA-F]{64}$')
);
CREATE INDEX IF NOT EXISTS ix_user_sessions_active_user
    ON user_sessions(user_id, company_id, expires_at) WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS auth_events (
    auth_event_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    company_id uuid REFERENCES companies(company_id) ON DELETE RESTRICT,
    user_id uuid REFERENCES users(user_id) ON DELETE RESTRICT,
    username_attempt varchar(100) NOT NULL,
    event_type varchar(40) NOT NULL CHECK (event_type IN
        ('login_succeeded','login_failed','account_locked','logout','session_revoked','password_changed','password_reset')),
    occurred_at timestamptz NOT NULL DEFAULT now(),
    correlation_id uuid,
    ip_address inet,
    user_agent varchar(1000),
    details jsonb
);
CREATE INDEX IF NOT EXISTS ix_auth_events_company_time
    ON auth_events(company_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS ix_auth_events_user_time
    ON auth_events(user_id, occurred_at DESC);

CREATE OR REPLACE FUNCTION enforce_user_session_company()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM users u
        WHERE u.user_id = NEW.user_id AND u.company_id = NEW.company_id
          AND u.is_active = true AND u.is_deleted = false
    ) THEN
        RAISE EXCEPTION 'auth_session_company_mismatch_or_inactive_user'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_user_sessions_company ON user_sessions;
CREATE TRIGGER trg_user_sessions_company
BEFORE INSERT OR UPDATE ON user_sessions
FOR EACH ROW EXECUTE FUNCTION enforce_user_session_company();
